"""Original axial and peripheral spondyloarthritis questions."""
from qbank_authoring import question,ref
rows=[]
S=ref('ASAS-EULAR axial spondyloarthritis recommendations: 2022 update','https://ard.bmj.com/content/82/1/19')
K=ref('Korean College of Rheumatology axial SpA recommendations: 2026 update','https://pmc.ncbi.nlm.nih.gov/articles/PMC13619551/')
P=ref('EULAR psoriatic arthritis management: 2023 update','https://pmc.ncbi.nlm.nih.gov/articles/PMC11103320/')
D=ref('ASAS recommendations: clinical information for axial SpA imaging referrals','https://ard.bmj.com/content/83/12/1636')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A 26-year-old man has 8 months of alternating buttock pain, prolonged morning stiffness and waking in the second half of the night. Exercise helps; rest does not. Which diagnosis is most likely?', 'Axial spondyloarthritis',[
 ('Lumbar spinal stenosis','This more often produces exertional leg symptoms relieved by flexion or sitting, particularly in an older patient.'),('Mechanical lumbar strain','Mechanical pain generally worsens with use and improves with rest; the chronic inflammatory pattern here is more suggestive of axial SpA.'),('Lumbar disc herniation with radiculopathy','Dermatomal pain, focal weakness or a tension sign would strengthen that diagnosis rather than alternating inflammatory buttock pain.')],
 'Recognize inflammatory back pain','**Young onset, insidious persistence, night symptoms and improvement with movement raise suspicion for axial SpA.**',['No single symptom establishes the diagnosis.','Ask about uveitis, psoriasis, bowel inflammation, family history and peripheral features.'], '**Assess the whole phenotype before ordering or interpreting imaging.**',['Examine spinal mobility, sacroiliac provocation, entheses and peripheral joints.','Exclude infection, malignancy and neurological emergencies when red flags are present.'],[['Inflammatory pattern','Often improves with activity'],['Mechanical pattern','Often related to loading'],['Axial SpA assessment','Clinical features plus imaging/laboratory context']],[S,D],style='clinical_scenario')

q('Which statement about HLA-B27 testing is correct?', 'It modifies diagnostic probability but neither confirms nor excludes axial spondyloarthritis by itself',[
 ('A positive result establishes axial SpA in any person with back pain','Many HLA-B27-positive people never develop axial SpA.'),('A negative result excludes axial SpA across all populations','Sensitivity varies by ancestry and phenotype, and HLA-B27-negative disease occurs.'),('Serial testing provides a disease activity measure','A genetic marker does not fluctuate with inflammatory activity.')],
 'Use HLA-B27 in the clinical context','**HLA-B27 is an association marker rather than a stand-alone diagnostic test.**',['Its predictive value depends on pretest probability and population prevalence.','It does not replace assessment for inflammatory symptoms or appropriate imaging.'], '**Avoid labeling incidental positivity as disease.**',['A negative result should not prevent referral when the phenotype is convincing.','Monitor activity with symptoms, examination and validated measures rather than repeated HLA typing.'],[['Positive','Raises probability in a suitable phenotype'],['Negative','Does not exclude'],['Serial typing','Not an activity test']],[D,S])

q('A woman has convincing inflammatory axial symptoms and MRI sacroiliitis, but no definite sacroiliitis on plain radiographs. Which designation may apply after appropriate clinical assessment?', 'Nonradiographic axial spondyloarthritis',[
 ('Radiographic axial spondyloarthritis solely because MRI is abnormal','The radiographic designation refers to definite structural sacroiliitis on plain radiographs.'),('Diffuse idiopathic skeletal hyperostosis','DISH is a different enthesopathic ossification phenotype and does not explain this inflammatory sacroiliitis presentation.'),('Rheumatoid spondylitis','RA does not typically present as this sacroiliac-predominant axial disease.')],
 'Nonradiographic does not mean noninflammatory','**The axial SpA spectrum includes patients without definite radiographic sacroiliitis.**',['MRI may detect active inflammatory lesions earlier than radiographs show structural change.','The absence of plain-film damage does not reliably indicate mild symptoms.'], '**Confirm that MRI findings fit the patient rather than using them in isolation.**',['Review mechanical stress and other mimics.','Treatment is based on activity, objective findings and the complete clinical assessment.'],[['Radiographic axial SpA','Definite radiographic sacroiliitis'],['Nonradiographic axial SpA','No definite radiographic sacroiliitis'],['MRI','Can show active or structural lesions']],[D,S],style='clinical_scenario')

q('Three months after childbirth, a woman with load-related pelvic pain has limited sacroiliac bone marrow edema on MRI and no other SpA features. What is the best interpretation?', 'Postpartum mechanical changes can mimic inflammatory sacroiliitis, so MRI must be interpreted with clinical context',[
 ('Any sacroiliac edema proves axial SpA','Bone marrow edema is not sufficiently specific in isolation.'),('HLA-B27 testing alone can determine whether the edema is inflammatory','A genetic association marker cannot independently establish the cause of an MRI lesion.'),('All postpartum sacroiliac lesions represent septic sacroiliitis','Infection requires assessment when clinically suspected but is not the explanation for all postpartum MRI changes.')],
 'Avoid overdiagnosing from an isolated imaging signal','**Pregnancy-related loading can produce sacroiliac edema resembling axial SpA.**',['Lesion distribution, structural changes, clinical phenotype and evolution affect interpretation.','Athletic loading and other mechanical conditions can also generate mimics.'], '**Provide pregnancy and activity history to the radiologist.**',['Reassess persistent inflammatory symptoms rather than assigning a diagnosis from a single minor lesion.','Investigate infection if severe focal pain, fever or other warning features are present.'],[['Postpartum state','Mechanical mimic possible'],['Bone marrow edema','Sensitive but not uniquely specific'],['Structural and clinical context','Improves interpretation']],[D,ref('Prospective study: postpartum SpA-like MRI lesions','https://ard.bmj.com/content/79/7/929')],style='clinical_scenario')

q('Which lesion represents enthesitis rather than synovitis?', 'Inflammation at the Achilles tendon insertion into the calcaneus',[
 ('Effusion and synovial hypertrophy inside the knee joint','This is synovitis.'),('Inflammation of the tendon sheath around the finger flexor tendon','This is tenosynovitis; it can coexist with enthesitis but is anatomically distinct.'),('Inflammation of the olecranon bursa','This is bursitis, not an insertional enthesis lesion.')],
 'Identify the anatomical inflammatory domain','**An enthesis is where a tendon, ligament or related structure attaches to bone.**',['Heel pain in SpA may reflect Achilles or plantar fascia insertion involvement.','Mechanical tendinopathy can mimic inflammatory enthesitis.'], '**Consider load, distribution and associated disease features.**',['Ultrasound or MRI may clarify selected uncertain cases.','An isolated painful insertion does not automatically establish a systemic inflammatory diagnosis.'],[['Enthesitis','Insertion at bone'],['Synovitis','Joint synovium'],['Tenosynovitis','Tendon sheath']],[P,K])

q('A patient with nail pitting and psoriasis develops uniform swelling of an entire toe. What is this finding called?', 'Dactylitis',[
 ('Isolated interphalangeal synovitis','An isolated joint swelling does not involve the whole digit.'),('A rheumatoid nodule','This is a discrete subcutaneous lesion, not diffuse swelling of a toe.'),('Tendon xanthoma','This reflects a lipid deposit and has a different clinical context and distribution.')],
 'Recognize whole-digit inflammation','**Dactylitis is diffuse swelling of a digit, often reflecting combined tendon, soft-tissue and joint inflammation.**',['It is a characteristic domain of psoriatic arthritis and other SpA phenotypes.','Infection and crystal disease can be mimics depending on the setting.'], '**Examine other disease domains and functional impact.**',['Assess nails, skin, peripheral joints, entheses and axial symptoms.','A hot painful digit with systemic illness needs urgent evaluation for infection.'],[['Whole digit','Dactylitis'],['One joint','Localized synovitis'],['Psoriasis plus dactylitis','Supports PsA phenotype']],[P],style='clinical_scenario')

q('Which hand radiographic pattern most strongly favors psoriatic arthritis over rheumatoid arthritis?', 'DIP-predominant erosions with adjacent new bone formation and pencil-in-cup change',[
 ('Symmetric MCP marginal erosions with periarticular osteopenia','This is more characteristic of RA.'),('Central DIP erosions with a gull-wing configuration and osteophytes','This favors erosive osteoarthritis.'),('Hook osteophytes at the second and third MCP joints with chondrocalcinosis','This raises concern for hemochromatosis-associated arthropathy or CPPD.')],
 'Look for simultaneous destruction and proliferation','**PsA can combine erosive change with juxta-articular bone formation.**',['DIP disease, nail changes and dactylitis strengthen the clinical interpretation.','Not every PsA patient develops the classic late pencil-in-cup appearance.'], '**Use imaging patterns to refine, not replace, clinical assessment.**',['Early films may be nondiagnostic.','Severe osteolysis can produce arthritis mutilans in a subset of patients.'],[['PsA','Erosion plus proliferation'],['RA','Marginal erosions/osteopenia'],['Erosive OA','Central erosions']],[P])

q('A man with chronic inflammatory back pain develops a painful red eye, photophobia and blurred vision. Which diagnosis is the priority?', 'Acute anterior uveitis',[
 ('Uncomplicated allergic conjunctivitis','Itching and bilateral irritation are more typical; pain, photophobia and visual change need urgent assessment.'),('Painless subconjunctival hemorrhage','This does not usually cause photophobia or blurred vision.'),('Age-related cataract','This causes gradual visual impairment rather than an acutely painful red eye.')],
 'A painful photophobic eye needs urgent assessment','**Acute anterior uveitis is an important extra-musculoskeletal manifestation of SpA.**',['Slit-lamp examination identifies anterior chamber inflammation.','Delayed treatment can threaten vision.'], '**Arrange urgent ophthalmic evaluation.**',['Topical anti-inflammatory and cycloplegic treatment is guided by ophthalmology.','Recurrent uveitis should influence systemic drug selection.'],[['Pain and photophobia','Uveitis warning symptoms'],['Slit lamp','Confirms anterior chamber inflammation'],['Recurrent episodes','Relevant to systemic treatment choice']],[S,K],style='clinical_scenario')

q('Which disease activity measure incorporates an acute-phase reactant into an axial SpA composite score?', 'ASDAS-CRP',[
 ('BASDAI','BASDAI is based on patient-reported symptoms and does not itself include CRP.'),('BASFI','BASFI assesses functional limitations rather than providing the same inflammatory activity composite.'),('Modified Schober measurement','This assesses lumbar mobility, not a CRP-containing activity score.')],
 'Distinguish activity, function and mobility','**ASDAS combines patient-reported items with an inflammatory marker.**',['BASDAI is useful for symptom burden but can be influenced by noninflammatory pain.','Functional and mobility measures answer related but different questions.'], '**Interpret scores alongside examination and comorbidities.**',['High symptom scores require assessment for active inflammation, structural disease and pain amplification.','A score should inform shared decisions rather than become an automatic prescription.'],[['ASDAS-CRP','Composite inflammatory activity'],['BASFI','Function'],['Schober','Spinal mobility']],[K,S])

q('Which is the most appropriate initial management combination for confirmed active axial SpA without contraindications?', 'Structured exercise/physiotherapy and an adequate NSAID trial',[
 ('Methotrexate monotherapy specifically to control isolated axial inflammation','Conventional DMARDs have not shown reliable efficacy for pure axial disease.'),('Hydroxychloroquine plus prolonged bed rest','This does not provide an evidence-based axial strategy and inactivity worsens function.'),('Long-term systemic prednisone as the main maintenance treatment','Long-term systemic glucocorticoids are not a recommended axial maintenance strategy.')],
 'Combine movement with appropriate symptom control','**Exercise is a core intervention, and NSAIDs are usual first-line pharmacological treatment.**',['Choose an NSAID and dose in light of renal, gastrointestinal and cardiovascular risks.','Assess benefit and tolerability rather than continuing ineffective treatment indefinitely.'], '**Tailor mobility, posture and strengthening work.**',['Smoking cessation and education belong in the care plan.','Persistent inflammatory activity despite conventional measures may require advanced treatment.'],[['Exercise','Function and mobility'],['NSAID','Initial pharmacological control'],['Persistent activity','Reassess and consider escalation']],[S,K])

q('A patient has persistent MRI-supported active axial SpA despite adequate trials of two NSAIDs. Which treatment is a suitable advanced option?', 'A TNF inhibitor or IL-17 inhibitor, selected according to the clinical phenotype and safety profile',[
 ('Hydroxychloroquine as the preferred axial disease-modifying agent','It lacks an established role for controlling isolated axial inflammation.'),('Sulfasalazine solely for axial symptoms without peripheral arthritis','Its possible peripheral role does not establish efficacy for pure axial disease.'),('An IL-23 inhibitor automatically because it treats skin psoriasis','Skin/peripheral PsA efficacy should not be assumed to establish axial SpA efficacy.')],
 'Escalate confirmed active axial disease','**Advanced therapy can be appropriate after inadequate conventional treatment.**',['TNF, IL-17 and selected JAK inhibition are options in applicable guidance and licensing.','Assess objective inflammation, infection risk and extra-musculoskeletal disease before selecting an agent.'], '**Reconfirm the diagnosis and inflammatory activity when response is poor.**',['Review adherence and noninflammatory causes of symptoms.','Drug choice should account for uveitis, IBD and psoriasis rather than the spine alone.'],[['TNF/IL-17 pathways','Established axial options'],['csDMARDs','Limited role in pure axial disease'],['Extra-musculoskeletal disease','Influences selection']],[S,K],style='clinical_scenario')

q('A patient has active axial SpA and recurrent anterior uveitis requiring systemic treatment. Which agent is generally favored among these choices?', 'Adalimumab',[
 ('Etanercept','Its protection against recurrent uveitis is less favorable than that of monoclonal TNF antibodies.'),('Secukinumab','IL-17 blockade can treat axial disease but is not the preferred choice for recurrent uveitis.'),('Ustekinumab','It is not an established axial SpA treatment and is not the preferred uveitis-directed choice.')],
 'Recurrent uveitis favors a monoclonal TNF antibody','**A monoclonal TNF inhibitor can address the axial disease and recurrent eye inflammation.**',['Etanercept is a receptor fusion protein and is not interchangeable for every extra-musculoskeletal indication.','Ophthalmology should guide acute and ongoing ocular management.'], '**Select by the complete phenotype.**',['Screen for relevant infections before advanced therapy.','Discuss individual contraindications and prior response.'],[['Adalimumab','Monoclonal TNF antibody'],['Etanercept','TNF receptor fusion protein'],['IL-17 blockade','Axial option but not preferred for recurrent uveitis']],[S,K],style='clinical_scenario')

q('A patient has active axial SpA and active Crohn disease. Which of the following is generally the most suitable shared-pathway option?', 'Infliximab',[
 ('Etanercept','It treats axial disease but is not an effective Crohn treatment.'),('Secukinumab','IL-17 inhibition is generally avoided in active IBD because of worsening concerns.'),('Methotrexate alone as reliably effective axial therapy','It does not provide reliable control of isolated axial inflammation.')],
 'Coordinate joint and bowel treatment','**A monoclonal TNF antibody with efficacy in both diseases is often a useful choice.**',['Not every drug within a broad inflammatory class treats both axial disease and IBD.','Other dual-indication options may be appropriate according to approvals, prior response and safety.'], '**Make the choice jointly with gastroenterology.**',['Distinguish active inflammatory bowel symptoms from noninflammatory causes.','Avoid treating spinal disease in a way likely to aggravate the bowel disease.'],[['Infliximab','Efficacy in axial disease and Crohn disease'],['Etanercept','Not an effective IBD treatment'],['IL-17 inhibitors','Avoid in active IBD']],[S,K],style='clinical_scenario')

q('A patient has active axial SpA and extensive plaque psoriasis but no IBD or recurrent uveitis. Which pathway can be especially attractive among axial-active choices?', 'IL-17 inhibition',[
 ('IL-6 receptor blockade','This is not a standard axial SpA strategy.'),('CD20 B-cell depletion','Rituximab is not an established routine axial SpA treatment.'),('IL-4/IL-13 blockade','This pathway is used for other diseases and is not an established axial-plus-psoriasis strategy.')],
 'Skin burden can influence the axial drug choice','**IL-17 inhibition has efficacy for axial disease and plaque psoriasis.**',['Treatment still depends on contraindications, prior exposure and patient preference.','Assess for IBD before using an IL-17-directed strategy.'], '**Match the mechanism to the dominant disease domains.**',['Review infection risks, including mucocutaneous Candida susceptibility.','A psoriasis-effective drug without axial efficacy should not be assumed equivalent.'],[['IL-17 inhibition','Axial and skin efficacy'],['IL-23 pathway','Skin/peripheral benefit does not prove axial efficacy'],['IL-6 blockade','Not standard axial treatment']],[S,K])

if __name__=='__main__':print(f'Spondyloarthritis draft: {len(rows)} questions')
